ng\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-cac26c30\"><h1 class=\"uagb-heading-text\">Chair Massage in Portland</h1></div>\n<!-- /wp:uagb/advanced-heading -->\n\n<!-- wp:uagb/image {\"block_id\":\"e4e3f4b0\",\"disableLazyLoad\":true,\"url\":\"{{IMG_URL_0}}\",\"urlTablet\":\"{{IMG_URL_0}}\",\"urlMobile\":\"{{IMG_URL_0}}\",\"alt\":\"Watercolor of a wooden chair in a garden, with a small flowering tree growing from its back.\",\"linkDestination\":\"none\",\"title\":\"Watercolor of a wooden chair in a garden, with a small flowering tree growing from its back.\",\"width\":396,\"widthTablet\":260,\"widthMobile\":800,\"height\":380,\"heightTablet\":250,\"heightMobile\":300,\"naturalWidth\":1024,\"naturalHeight\":1024,\"sizeSlug\":\"custom\",\"sizeSlugTablet\":\"custom\",\"sizeSlugMobile\":\"custom\",\"imageTopMargin\":0,\"imageRightMargin\":0,\"imageLeftMargin\":0,\"imageBottomMargin\":-180,\"imageTopMarginTablet\":0,\"imageRightMarginTablet\":0,\"imageLeftMarginTablet\":0,\"imageBottomMarginTablet\":-120,\"imageTopMarginMobile\":0,\"imageRightMarginMobile\":0,\"imageLeftMarginMobile\":0,\"imageBottomMarginMobile\":-80,\"imageMarginLink\":false,\"objectFit\":\"cover\",\"objectFitTablet\":\"cover\",\"objectFitMobile\":\"cover\",\"imageBoxShadowVOffset\":2,\"imageBoxShadowBlur\":5,\"imageBoxShadowSpread\":-1,\"customHeightSetDesktop\":true,\"customHeightSetTablet\":true,\"customHeightSetMobile\":true,\"imageBorderTopLeftRadius\":20,\"imageBorderTopRightRadius\":20,\"imageBorderBottomLeftRadius\":20,\"imageBorderBottomRightRadius\":20,\"imageBorderTopLeftRadiusTablet\":16,\"imageBorderTopRightRadiusTablet\":16,\"imageBorderBottomLeftRadiusTablet\":16,\"imageBorderBottomRightRadiusTablet\":16,\"imageBorderTopLeftRadiusMobile\":14,\"imageBorderTopRightRadiusMobile\":14,\"imageBorderBottomLeftRadiusMobile\":14,\"imageBorderBottomRightRadiusMobile\":14} -->\n<div class=\"wp-block-uagb-image uagb-block-e4e3f4b0 wp-block-uagb-image--layout-default wp-block-uagb-image--effect-static wp-block-uagb-image--align-none\"><figure class=\"wp-block-uagb-image__figure\"><img srcset=\"{{IMG_URL_0}} ,{{IMG_URL_0}} 780w, {{IMG_URL_0}} 360w\" sizes=\"(max-width: 480px) 150px\" src=\"{{IMG_URL_0}}\" alt=\"Watercolor of a wooden chair in a garden, with a small flowering tree growing from its back.\" width=\"396\" height=\"380\" title=\"Watercolor of a wooden chair in a garden, with a small flowering tree growing from its back.\" role=\"img\"/></figure></div>\n<!-- /wp:uagb/image --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"a7f70b8b\",\"topPaddingDesktop\":180,\"bottomPaddingDesktop\":60,\"leftPaddingDesktop\":40,\"rightPaddingDesktop\":40,\"topPaddingTablet\":140,\"bottomPaddingTablet\":0,\"leftPaddingTablet\":32,\"rightPaddingTablet\":32,\"topPaddingMobile\":140,\"bottomPaddingMobile\":0,\"leftPaddingMobile\":24,\"rightPaddingMobile\":24,\"paddingLink\":false,\"variationSelected\":true,\"rowGapDesktop\":40,\"rowGapTablet\":40,\"rowGapMobile\":30,\"isBlockRootParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-a7f70b8b alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/container {\"block_id\":\"e70f6224\",\"bottomPaddingDesktop\":40,\"topPaddingTablet\":0,\"bottomPaddingTablet\":40,\"leftPaddingTablet\":0,\"rightPaddingTablet\":0,\"topPaddingMobile\":0,\"bottomPaddingMobile\":30,\"leftPaddingMobile\":0,\"rightPaddingMobile\":0,\"paddingLink\":false,\"containerBorderTopWidth\":0,\"containerBorderLeftWidth\":0,\"containerBorderRightWidth\":0,\"containerBorderBottomWidth\":1,\"containerBorderLink\":false,\"containerBorderStyle\":\"solid\",\"containerBorderColor\":\"var(\\u002d\\u002dast-global-color-6)\"} -->\n<div class=\"wp-block-uagb-container uagb-block-e70f6224\"><!-- wp:uagb/advanced-heading {\"block_id\":\"865b52e6\",\"classMigrate\":true,\"headingDescToggle\":true,\"subHeadingColor\":\"\",\"headSpace\":8,\"subHeadSpace\":0,\"blockTopPadding\":0,\"blockRightPadding\":420,\"blockBottomPadding\":0,\"blockLeftPadding\":0,\"blockTopPaddingTablet\":0,\"blockRightPaddingTablet\":0,\"blockBottomPaddingTablet\":0,\"blockLeftPaddingTablet\":0,\"blockTopPaddingMobile\":0,\"blockRightPaddingMobile\":0,\"blockBottomPaddingMobile\":0,\"blockLeftPaddingMobile\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-865b52e6\"><h2 class=\"uagb-heading-text\">What Is Chair Massage?</h2><p class=\"uagb-desc-text\">Chair massage is a short massage you receive sitting up, fully clothed, in a padded portable chair that supports your chest, arms and head as you lean forward. I work through your clothing without oil, mostly on the back, shoulders, neck, arms and hands. A session usually lasts 10 to 20 minutes. The chair folds up and fits in a quiet corner, which is why chair massage is what I bring to employee appreciation days and workplace events.<br><br>Most research on chair massage comes from small studies in workplaces and hospitals, usually with 15-minute sessions. In 52 employees, a 15-minute chair massage at work was followed by lower blood pressure, although the study had no comparison group.<a href=\"https://pubmed.ncbi.nlm.nih.gov/9132704/\">[1]</a> In 38 nurses offered a weekly 15-minute chair massage for 10 weeks, perceived-stress scores were lower at the end.<a href=\"https://pubmed.ncbi.nlm.nih.gov/23059434/\">[2]</a> In a randomized trial of 60 women on oncology nursing teams, 15-minute chair massages twice a week for three weeks were followed by lower stress scores, and less interference from pain in daily life, than no massage.<a href=\"https://pubmed.ncbi.nlm.nih.gov/34484493/\">[3]</a> Studies of office workers given short chair massages over a month report less neck and back discomfort,<a href=\"https://pubmed.ncbi.nlm.nih.gov/21688984/\">[4]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/28157084/\">[5]</a> and one found a higher tolerance for pressure on tender muscle points.<a href=\"https://pubmed.ncbi.nlm.nih.gov/28157084/\">[5]</a> These studies are small and short. I summarize them, including the weaker results, in the research section below.<br><br>Chair massage is hands-on work by a licensed massage therapist, adapted to you as you give feedback. It is not a mechanical massage chair, and studies of those devices are not included here.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"56f8e8ed\",\"bottomPaddingDesktop\":40,\"topPaddingTablet\":0,\"bottomPaddingTablet\":40,\"leftPaddingTablet\":0,\"rightPaddingTablet\":0,\"topPaddingMobile\":0,\"bottomPaddingMobile\":30,\"leftPaddingMobile\":0,\"rightPaddingMobile\":0,\"paddingLink\":false,\"containerBorderTopWidth\":0,\"containerBorderLeftWidth\":0,\"containerBorderRightWidth\":0,\"containerBorderBottomWidth\":1,\"containerBorderLink\":false,\"containerBorderStyle\":\"solid\",\"containerBorderColor\":\"var(\\u002d\\u002dast-global-color-6)\"} -->\n<div class=\"wp-block-uagb-container uagb-block-56f8e8ed\"><!-- wp:uagb/advanced-heading {\"block_id\":\"83659ea6\",\"classMigrate\":true,\"headingDescToggle\":true,\"subHeadingColor\":\"\",\"headSpace\":8,\"subHeadSpace\":0,\"blockTopPadding\":0,\"blockRightPadding\":420,\"blockBottomPadding\":0,\"blockLeftPadding\":0,\"blockTopPaddingTablet\":0,\"blockRightPaddingTablet\":0,\"blockBottomPaddingTablet\":0,\"blockLeftPaddingTablet\":0,\"blockTopPaddingMobile\":0,\"blockRightPaddingMobile\":0,\"blockBottomPaddingMobile\":0,\"blockLeftPaddingMobile\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-83659ea6\"><h2 class=\"uagb-heading-text\">Common Reasons Clients Choose Chair Massage</h2><p class=\"uagb-desc-text\">People often choose chair massage when hours at a desk, on the phone or on their feet leave the neck, shoulders and upper back tight, and they want attention to those areas without changing clothes or taking an hour away from work. Others like it as a pause in a busy day, or as a first massage, since you stay dressed and the session is short. Employers book it for appreciation days and events, where each person takes a short turn in the chair.<br><br>Research on chair massage for desk work points the same way, with limits. In 50 office workers, half had eight 15-minute chair massages during work breaks over four weeks and half had none; the massage group reported less pain in the upper and lower spine and the right arm, with smaller improvements in the right shoulder and left forearm, and tolerated more pressure on the muscle points tested before it hurt, most of all in the trapezius and supraspinatus muscles, while changes in the control group were not statistically significant.<a href=\"https://pubmed.ncbi.nlm.nih.gov/28157084/\">[5]</a> In 124 computer workers randomly split among four weeks of chair massage, relaxing-music sessions or no intervention, the massage group had higher pressure-pain thresholds in every neck muscle tested and a higher relaxation level measured from heart-rate variability; the music group improved on relaxation but its pain thresholds were unchanged, falling in one muscle, and changes in the no-intervention group were negligible.<a href=\"https://pubmed.ncbi.nlm.nih.gov/28721578/\">[6]</a> In 19 women in administration and management who had chair massage twice a week for a month, neck and upper-back discomfort scores fell and the neck bent further to the side and backward, although all 19 received the massage, with no separate control group, and only 15 completed the study.<a href=\"https://pubmed.ncbi.nlm.nih.gov/21688984/\">[4]</a><br><br>Before I begin, I ask about your preferences and anything I should know about your health. You can request lighter pressure, a different focus, or a pause at any time.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"b09e52a7\",\"bottomPaddingDesktop\":0,\"paddingLink\":false,\"containerBorderTopWidth\":0,\"containerBorderLeftWidth\":0,\"containerBorderRightWidth\":0,\"containerBorderBottomWidth\":0,\"containerBorderLink\":false,\"containerBorderStyle\":\"none\"} -->\n<div class=\"wp-block-uagb-container uagb-block-b09e52a7\"><!-- wp:uagb/advanced-heading {\"block_id\":\"aff31cd8\",\"classMigrate\":true,\"headingDescToggle\":true,\"subHeadingColor\":\"\",\"headSpace\":8,\"subHeadSpace\":0,\"blockTopPadding\":0,\"blockRightPadding\":420,\"blockBottomPadding\":0,\"blockLeftPadding\":0,\"blockTopPaddingTablet\":0,\"blockRightPaddingTablet\":0,\"blockBottomPaddingTablet\":0,\"blockLeftPaddingTablet\":0,\"blockTopPaddingMobile\":0,\"blockRightPaddingMobile\":0,\"blockBottomPaddingMobile\":0,\"blockLeftPaddingMobile\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-aff31cd8\"><h2 class=\"uagb-heading-text\">Who Can Benefit From Chair Massage?</h2><p class=\"uagb-desc-text\">Chair massage suits people who want focused attention on the back, neck and shoulders in a short session, and groups where many people will take a turn. You do not need to undress or to have had a massage before, and you can ask me to stay with one area or to work more lightly. If you have an ongoing health condition, a recent injury or surgery, or you are pregnant, tell me at the start. I will keep the work within the scope of massage, adapt it or leave parts out, and I will tell you if I think you should check with a doctor first. If the chair itself is not comfortable for you, say so: I can adjust it or work with you seated upright in an ordinary chair.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"e4ef3a0d\",\"bottomPaddingDesktop\":0,\"paddingLink\":false,\"containerBorderTopWidth\":0,\"containerBorderLeftWidth\":0,\"containerBorderRightWidth\":0,\"containerBorderBottomWidth\":0,\"containerBorderLink\":false,\"containerBorderStyle\":\"none\"} -->\n<div class=\"wp-block-uagb-container uagb-block-e4ef3a0d\"><!-- wp:uagb/advanced-heading {\"block_id\":\"6fedef09\",\"classMigrate\":true,\"headingDescToggle\":false,\"headingDescPosition\":\"above-heading\",\"headingAlign\":\"center\",\"separatorColor\":\"var(\\u002d\\u002dast-global-color-0)\",\"seperatorStyle\":\"solid\",\"seperatorPosition\":\"above-heading\",\"separatorWidth\":64,\"separatorWidthType\":\"px\",\"headSpace\":0,\"separatorSpace\":14,\"blockTopPadding\":100,\"blockRightPadding\":220,\"blockLeftPadding\":220,\"blockBottomPadding\":0,\"blockTopPaddingTablet\":80,\"blockRightPaddingTablet\":40,\"blockLeftPaddingTablet\":40,\"blockBottomPaddingTablet\":0,\"blockTopPaddingMobile\":60,\"blockRightPaddingMobile\":0,\"blockLeftPaddingMobile\":0,\"blockBottomPaddingMobile\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-6fedef09\"><div class=\"uagb-separator\"></div><h2 class=\"uagb-heading-text\">Questions About Chair Massage</h2></div>\n<!-- /wp:uagb/advanced-heading -->\n\n<!-- wp:uagb/faq {\"block_id\":\"744d97ec\",\"borderStyle\":\"\",\"borderWidth\":\"\",\"borderRadius\":\"\",\"borderColor\":\"\",\"overallBorderTopWidth\":1,\"overallBorderLeftWidth\":1,\"overallBorderRightWidth\":1,\"overallBorderBottomWidth\":1,\"overallBorderTopLeftRadius\":2,\"overallBorderTopRightRadius\":2,\"overallBorderBottomLeftRadius\":2,\"overallBorderBottomRightRadius\":2,\"overallBorderStyle\":\"solid\",\"overallBorderColor\":\"#D2D2D2\"} -->\n<div class=\"wp-block-uagb-faq uagb-faq__outer-wrap uagb-block-744d97ec uagb-faq-icon-row uagb-faq-layout-accordion uagb-faq-expand-first-true uagb-faq-inactive-other-true uagb-faq-equal-height\" data-faqtoggle=\"true\" role=\"tablist\"><!-- wp:uagb/faq-child {\"block_id\":\"91acb9be\",\"question\":\"Do I Need to Undress for Chair Massage?\",\"answer\":\"No. You stay fully clothed, and I do not use oil. Light layers are easiest to work through; a thick coat or a bulky hood is better taken off.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"0b40fe3b\",\"question\":\"How Long Is a Chair Massage?\",\"answer\":\"At corporate and group events I plan about 10 to 15 minutes per person, depending on the schedule and how many people take part. The Corporate and Group Massage page explains how the time block is planned. The studies summarized below mostly used 15-minute sessions.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"f6df4581\",\"question\":\"What Is the Massage Chair Like?\",\"answer\":\"It is a padded folding chair that you sit on facing forward, with your knees on supports, your chest against a cushion and your face in a cradle, so your back, neck and shoulders are easy to reach. I adjust it to your height. If kneeling or leaning forward is uncomfortable, I can work with you seated upright in an ordinary chair.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"d7a89382\",\"question\":\"Is Chair Massage the Same as a Mechanical Massage Chair?\",\"answer\":\"No. A massage chair is a machine with rollers. Chair massage is hands-on work by a licensed massage therapist in a portable chair, adapted to you as you give feedback.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"858eb2df\",\"question\":\"How Much Pressure Will You Use?\",\"answer\":\"Enough to reach the tight muscles, and no more than you want. Tell me what you like, and ask me to lighten up or press more firmly at any time; I will adjust.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"03e440fc\",\"question\":\"How Is Chair Massage Different From Your Other Sessions?\",\"answer\":\"Chair massage is seated, clothed and short, and it focuses on the back, shoulders, neck, arms and hands. Therapeutic massage and deep tissue massage take place on a table, last longer and can cover the whole body. Thai massage is done on a mat and adds assisted stretching. Each is described on its own page.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"dadc3bce\",\"question\":\"Can I Have a Chair Massage If I’m Pregnant or Have a Health Condition?\",\"answer\":\"Often yes, with changes. Tell me before I start about any health conditions, medications, pregnancy, recent injury or surgery. I may adjust the work, leave an area out, or suggest you check with your clinician first.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"2717f247\",\"question\":\"Will I Feel the Results Right Away?\",\"answer\":\"People respond differently to massage, so I can’t promise a particular result or timeline. I will ask how the session feels and adjust as I go.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"8318cff9\",\"question\":\"What Does the Host Need to Provide?\",\"answer\":\"A quiet corner with roughly six feet by six feet of floor space, somewhere for people to wait, and a way for them to sign up for a time. I bring the chair and everything else. The Corporate and Group Massage page lists what I plan with you before the event.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"91a854c0\",\"question\":\"Where Do Sessions Take Place?\",\"answer\":\"Right now I offer corporate and group massage only, at suitable Portland venues, with bookings beginning November 14, 2026. Individual appointments at a dedicated Thai Solitude location are planned for summer 2027. I do not offer individual house calls.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /-->\n\n<!-- wp:uagb/faq-child {\"block_id\":\"b1c7f960\",\"question\":\"How Do I Book a Session?\",\"answer\":\"Corporate and group massage bookings begin November 14, 2026. The Corporate and Group Massage page explains how to request a quote. Individual appointments are planned for summer 2027.\",\"icon\":\"chevron-up\",\"iconActive\":\"chevron-down\"} /--></div>\n<!-- /wp:uagb/faq --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/advanced-heading {\"block_id\":\"f9c378da\",\"classMigrate\":true,\"headingDescToggle\":false,\"headingDescPosition\":\"above-heading\",\"headingAlign\":\"center\",\"separatorColor\":\"var(\\u002d\\u002dast-global-color-0)\",\"seperatorStyle\":\"solid\",\"seperatorPosition\":\"above-heading\",\"separatorWidth\":64,\"separatorWidthType\":\"px\",\"headSpace\":0,\"separatorSpace\":14,\"blockTopPadding\":100,\"blockRightPadding\":220,\"blockLeftPadding\":220,\"blockBottomPadding\":0,\"blockTopPaddingTablet\":80,\"blockRightPaddingTablet\":40,\"blockLeftPaddingTablet\":40,\"blockBottomPaddingTablet\":0,\"blockTopPaddingMobile\":60,\"blockRightPaddingMobile\":0,\"blockLeftPaddingMobile\":0,\"blockBottomPaddingMobile\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-f9c378da\"><div class=\"uagb-separator\"></div><h2 class=\"uagb-heading-text\">What To Expect During Your Appointment</h2></div>\n<!-- /wp:uagb/advanced-heading --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:paragraph -->\n<p>Before your session, tell me about any health conditions, medications, pregnancy, recent injury or surgery. I may adjust the work, or suggest you check with your clinician first. New numbness, weakness, unexplained swelling or radiating pain means you should see a doctor before massage.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:uagb/container {\"block_id\":\"8c452dec\",\"topPaddingDesktop\":0,\"bottomPaddingDesktop\":100,\"leftPaddingDesktop\":40,\"rightPaddingDesktop\":40,\"topPaddingTablet\":40,\"bottomPaddingTablet\":80,\"leftPaddingTablet\":32,\"rightPaddingTablet\":32,\"topPaddingMobile\":40,\"bottomPaddingMobile\":64,\"leftPaddingMobile\":24,\"rightPaddingMobile\":24,\"paddingLink\":false,\"variationSelected\":true,\"rowGapDesktop\":30,\"rowGapTablet\":20,\"rowGapMobile\":20,\"columnGapDesktop\":30,\"columnGapTablet\":20,\"isBlockRootParent\":true,\"layout\":\"grid\",\"gridColumnDesktop\":[{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}},{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}}],\"gridColumnTablet\":[{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}},{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"fr\",\"value\":1}}]} -->\n<div class=\"wp-block-uagb-container uagb-layout-grid uagb-block-8c452dec alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/container {\"block_id\":\"0771d027\",\"justifyContentDesktop\":\"flex-start\",\"topPaddingDesktop\":40,\"bottomPaddingDesktop\":40,\"leftPaddingDesktop\":40,\"rightPaddingDesktop\":40,\"topPaddingTablet\":32,\"bottomPaddingTablet\":32,\"leftPaddingTablet\":32,\"rightPaddingTablet\":32,\"topPaddingMobile\":24,\"bottomPaddingMobile\":24,\"leftPaddingMobile\":24,\"rightPaddingMobile\":24,\"containerBorderTopWidth\":1,\"containerBorderLeftWidth\":1,\"containerBorderRightWidth\":1,\"containerBorderBottomWidth\":1,\"containerBorderTopLeftRadius\":20,\"containerBorderTopRightRadius\":20,\"containerBorderBottomLeftRadius\":20,\"containerBorderBottomRightRadius\":20,\"containerBorderTopLeftRadiusTablet\":16,\"containerBorderTopRightRadiusTablet\":16,\"containerBorderBottomLeftRadiusTablet\":16,\"containerBorderBottomRightRadiusTablet\":16,\"containerBorderTopLeftRadiusMobile\":14,\"containerBorderTopRightRadiusMobile\":14,\"containerBorderBottomLeftRadiusMobile\":14,\"containerBorderBottomRightRadiusMobile\":14,\"containerBorderStyle\":\"solid\",\"containerBorderColor\":\"var(\\u002d\\u002dast-global-color-6)\",\"isGridCssInParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-0771d027\"><!-- wp:uagb/advanced-heading {\"block_id\":\"78b38aa2\",\"classMigrate\":true,\"headingDescToggle\":true,\"headingColor\":\"var(\\u002d\\u002dast-global-color-2)\",\"subHeadingColor\":\"\",\"headingTag\":\"p\",\"headSpace\":10,\"subHeadSpace\":0,\"headFontSize\":24,\"headFontSizeTablet\":22,\"headFontSizeMobile\":20,\"headLineHeight\":1.3000000000000000444089209850062616169452667236328125} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-78b38aa2\"><p class=\"uagb-heading-text\">Quick Check-In</p><p class=\"uagb-desc-text\">Before you sit down, I ask where you feel tension, how much pressure you like, and anything about your health I should know. At a group event this takes a minute or two.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"74630f60\",\"justifyContentDesktop\":\"flex-start\",\"topPaddingDesktop\":40,\"bottomPaddingDesktop\":40,\"leftPaddingDesktop\":40,\"rightPaddingDesktop\":40,\"topPaddingTablet\":32,\"bottomPaddingTablet\":32,\"leftPaddingTablet\":32,\"rightPaddingTablet\":32,\"topPaddingMobile\":24,\"bottomPaddingMobile\":24,\"leftPaddingMobile\":24,\"rightPaddingMobile\":24,\"containerBorderTopWidth\":1,\"containerBorderLeftWidth\":1,\"containerBorderRightWidth\":1,\"containerBorderBottomWidth\":1,\"containerBorderTopLeftRadius\":20,\"containerBorderTopRightRadius\":20,\"containerBorderBottomLeftRadius\":20,\"containerBorderBottomRightRadius\":20,\"containerBorderTopLeftRadiusTablet\":16,\"containerBorderTopRightRadiusTablet\":16,\"containerBorderBottomLeftRadiusTablet\":16,\"containerBorderBottomRightRadiusTablet\":16,\"containerBorderTopLeftRadiusMobile\":14,\"containerBorderTopRightRadiusMobile\":14,\"containerBorderBottomLeftRadiusMobile\":14,\"containerBorderBottomRightRadiusMobile\":14,\"containerBorderStyle\":\"solid\",\"containerBorderColor\":\"var(\\u002d\\u002dast-global-color-6)\",\"isGridCssInParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-74630f60\"><!-- wp:uagb/advanced-heading {\"block_id\":\"05fef95b\",\"classMigrate\":true,\"headingDescToggle\":true,\"headingColor\":\"var(\\u002d\\u002dast-global-color-2)\",\"subHeadingColor\":\"\",\"headingTag\":\"p\",\"headSpace\":10,\"subHeadSpace\":0,\"headFontSize\":24,\"headFontSizeTablet\":22,\"headFontSizeMobile\":20,\"headLineHeight\":1.3000000000000000444089209850062616169452667236328125} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-05fef95b\"><p class=\"uagb-heading-text\">Settling Into the Chair</p><p class=\"uagb-desc-text\">I adjust the chair to your height and show you how to rest your chest, arms and face. If anything is uncomfortable, I change it before I begin.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"ce2bb769\",\"justifyContentDesktop\":\"flex-start\",\"topPaddingDesktop\":40,\"bottomPaddingDesktop\":40,\"leftPaddingDesktop\":40,\"rightPaddingDesktop\":40,\"topPaddingTablet\":32,\"bottomPaddingTablet\":32,\"leftPaddingTablet\":32,\"rightPaddingTablet\":32,\"topPaddingMobile\":24,\"bottomPaddingMobile\":24,\"leftPaddingMobile\":24,\"rightPaddingMobile\":24,\"containerBorderTopWidth\":1,\"containerBorderLeftWidth\":1,\"containerBorderRightWidth\":1,\"containerBorderBottomWidth\":1,\"containerBorderTopLeftRadius\":20,\"containerBorderTopRightRadius\":20,\"containerBorderBottomLeftRadius\":20,\"containerBorderBottomRightRadius\":20,\"containerBorderTopLeftRadiusTablet\":16,\"containerBorderTopRightRadiusTablet\":16,\"containerBorderBottomLeftRadiusTablet\":16,\"containerBorderBottomRightRadiusTablet\":16,\"containerBorderTopLeftRadiusMobile\":14,\"containerBorderTopRightRadiusMobile\":14,\"containerBorderBottomLeftRadiusMobile\":14,\"containerBorderBottomRightRadiusMobile\":14,\"containerBorderStyle\":\"solid\",\"containerBorderColor\":\"var(\\u002d\\u002dast-global-color-6)\",\"isGridCssInParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-ce2bb769\"><!-- wp:uagb/advanced-heading {\"block_id\":\"084d247e\",\"classMigrate\":true,\"headingDescToggle\":true,\"headingColor\":\"var(\\u002d\\u002dast-global-color-2)\",\"subHeadingColor\":\"\",\"headingTag\":\"p\",\"headSpace\":10,\"subHeadSpace\":0,\"headFontSize\":24,\"headFontSizeTablet\":22,\"headFontSizeMobile\":20,\"headLineHeight\":1.3000000000000000444089209850062616169452667236328125} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-084d247e\"><p class=\"uagb-heading-text\">Chair Massage Work</p><p class=\"uagb-desc-text\">I work through your clothing on the back, shoulders, neck, arms and hands, starting with broad pressure and spending more time where you asked. You can ask for a change at any point.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"af787552\",\"justifyContentDesktop\":\"flex-start\",\"topPaddingDesktop\":40,\"bottomPaddingDesktop\":40,\"leftPaddingDesktop\":40,\"rightPaddingDesktop\":40,\"topPaddingTablet\":32,\"bottomPaddingTablet\":32,\"leftPaddingTablet\":32,\"rightPaddingTablet\":32,\"topPaddingMobile\":24,\"bottomPaddingMobile\":24,\"leftPaddingMobile\":24,\"rightPaddingMobile\":24,\"containerBorderTopWidth\":1,\"containerBorderLeftWidth\":1,\"containerBorderRightWidth\":1,\"containerBorderBottomWidth\":1,\"containerBorderTopLeftRadius\":20,\"containerBorderTopRightRadius\":20,\"containerBorderBottomLeftRadius\":20,\"containerBorderBottomRightRadius\":20,\"containerBorderTopLeftRadiusTablet\":16,\"containerBorderTopRightRadiusTablet\":16,\"containerBorderBottomLeftRadiusTablet\":16,\"containerBorderBottomRightRadiusTablet\":16,\"containerBorderTopLeftRadiusMobile\":14,\"containerBorderTopRightRadiusMobile\":14,\"containerBorderBottomLeftRadiusMobile\":14,\"containerBorderBottomRightRadiusMobile\":14,\"containerBorderStyle\":\"solid\",\"containerBorderColor\":\"var(\\u002d\\u002dast-global-color-6)\",\"isGridCssInParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-af787552\"><!-- wp:uagb/advanced-heading {\"block_id\":\"f14b2a44\",\"classMigrate\":true,\"headingDescToggle\":true,\"headingColor\":\"var(\\u002d\\u002dast-global-color-2)\",\"subHeadingColor\":\"\",\"headingTag\":\"p\",\"headSpace\":10,\"subHeadSpace\":0,\"headFontSize\":24,\"headFontSizeTablet\":22,\"headFontSizeMobile\":20,\"headLineHeight\":1.3000000000000000444089209850062616169452667236328125} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-f14b2a44\"><p class=\"uagb-heading-text\">Before You Go</p><p class=\"uagb-desc-text\">At the end, I ask how the work felt, and you can take a moment before standing up.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/advanced-heading {\"block_id\":\"f30c80fe\",\"classMigrate\":true,\"headingDescToggle\":false,\"headingDescPosition\":\"above-heading\",\"headingAlign\":\"center\",\"separatorColor\":\"var(--ast-global-color-0)\",\"seperatorStyle\":\"solid\",\"seperatorPosition\":\"above-heading\",\"separatorWidth\":64,\"separatorWidthType\":\"px\",\"headSpace\":0,\"separatorSpace\":14,\"blockTopPadding\":100,\"blockRightPadding\":220,\"blockLeftPadding\":220,\"blockBottomPadding\":28,\"blockTopPaddingTablet\":80,\"blockRightPaddingTablet\":40,\"blockLeftPaddingTablet\":40,\"blockBottomPaddingTablet\":24,\"blockTopPaddingMobile\":60,\"blockRightPaddingMobile\":0,\"blockLeftPaddingMobile\":0,\"blockBottomPaddingMobile\":20} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-f30c80fe\"><div class=\"uagb-separator\"></div><h2 class=\"uagb-heading-text\">What the Research Says About Chair Massage</h2></div>\n<!-- /wp:uagb/advanced-heading -->\n\n<!-- wp:paragraph -->\n<p>Research on chair massage is smaller than the research on massage in general, and it has the same limits: most studies are small, many have no comparison group, results often depend on what massage is compared with, and few follow people for more than a few weeks. Most were done in workplaces and hospitals, usually with sessions of about 15 minutes, though some used 20- or 30-minute sessions and several reports do not give the length. The summaries below describe what the studies reported. They are general information, not medical advice or a promise of any result, and people respond differently. This section covers hands-on chair and seated massage and brief massage given at work; studies of mechanical massage chairs, and of massage given to patients as part of their care, are not summarized here. Each part starts with what the studies found in massage’s favor, then gives the results that were weaker, mixed or negative, and ends on what is encouraging: I included the studies I found with disappointing results, not only the favorable ones.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:details {\"showContent\":true,\"style\":{\"border\":{\"width\":\"1px\",\"style\":\"solid\",\"color\":\"var(\\u002d\\u002dts-rule)\",\"radius\":\"4px\"},\"color\":{\"background\":\"var(\\u002d\\u002dts-panel)\"},\"spacing\":{\"padding\":{\"top\":\"0.85rem\",\"right\":\"1.1rem\",\"bottom\":\"0.85rem\",\"left\":\"1.1rem\"},\"margin\":{\"bottom\":\"0.7rem\"}},\"typography\":{\"fontWeight\":\"600\"}}} -->\n<details class=\"wp-block-details has-border-color has-background\" style=\"border-color:var(--ts-rule);border-width:1px;border-style:solid;border-radius:4px;background-color:var(--ts-panel);padding-top:0.85rem;padding-right:1.1rem;padding-bottom:0.85rem;padding-left:1.1rem;margin-bottom:0.7rem;font-weight:600\" open><summary>Reviews, and What They Say About Limits</summary>\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">I did not find a systematic review of chair massage on its own, so the reviews that apply are of massage in general and of massage for people under stress at work. Reviews of massage for pain that rated how certain their evidence was reached a consistent point in massage’s favor: every conclusion rated moderate-certainty found massage associated with less pain, and a meta-analysis of 67 randomized trials found lower pain scores after massage than after sham massage, no massage or other approaches.<a href=\"https://pubmed.ncbi.nlm.nih.gov/39008297/\">[7]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/27165971/\">[8]</a> A 2021 network meta-analysis of 15 randomized trials with 688 health care workers found that physical relaxation methods as a group reduced measures of occupational stress compared with no intervention, and that massage therapy on its own was one of only two methods, with yoga, that did better than control.<a href=\"https://pubmed.ncbi.nlm.nih.gov/34235817/\">[9]</a> A 2004 meta-analysis of 37 randomized studies found that a single massage was followed by lower state anxiety, blood pressure and heart rate, with the largest effects, on trait anxiety and depression, coming after a course of sessions.<a href=\"https://pubmed.ncbi.nlm.nih.gov/14717648/\">[10]</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">The same reviews are careful about limits. None of the conclusions in the 2024 review was rated high-certainty, and conclusions backed by moderate- or high-certainty evidence that massage was better than other active approaches were rare.<a href=\"https://pubmed.ncbi.nlm.nih.gov/39008297/\">[7]</a> An earlier evidence map of 49 systematic reviews found that the high-quality reviews reached conclusions of low strength of evidence, because few large, rigorous studies had been done.<a href=\"https://pubmed.ncbi.nlm.nih.gov/30892910/\">[11]</a> In the network meta-analysis, yoga was identified as the best method and massage’s effect was smaller.<a href=\"https://pubmed.ncbi.nlm.nih.gov/34235817/\">[9]</a> A 2019 systematic review of 10 studies of aromatherapy and massage for stress in nurses, four of them of massage alone, found that most reported a benefit but that the studies were few and at high or unclear risk of bias, and concluded that the evidence does not sufficiently prove that massage reduces nurses’ job-related stress.<a href=\"https://pubmed.ncbi.nlm.nih.gov/29964364/\">[12]</a> The 2004 meta-analysis found no lower negative mood, cortisol or less immediate pain after a single massage.<a href=\"https://pubmed.ncbi.nlm.nih.gov/14717648/\">[10]</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">Massage is generally described as low risk, and where serious problems on record can be traced to who gave the massage, they are mostly tied to people who were not trained massage therapists. The U.S. National Center for Complementary and Integrative Health notes that the risk of harm appears to be low, although rare serious side effects such as a blood clot, nerve injury or bone fracture have been reported.<a href=\"https://www.nccih.nih.gov/health/massage-therapy-what-you-need-to-know\">[13]</a> A 2014 review of 40 published reports found 138 adverse events over 11 years, mainly disc herniation, soft-tissue injury, nerve problems, spinal cord injury and tears in the neck arteries, with spinal manipulation inside a massage repeatedly linked to the serious ones. Massage therapists were the practitioners in only 8 of the 138 events (5.8 percent) and chiropractors in 33 (23.9 percent); the rest (70.3 percent) involved unregistered people or other health professionals, and the authors concluded that massage by nonprofessionals and forceful techniques is often associated with adverse events.<a href=\"https://pubmed.ncbi.nlm.nih.gov/25197310/\">[14]</a> A 2003 review of 16 case reports and four case series likewise found that most adverse effects followed exotic techniques or massage by laypeople, with massage therapists rarely implicated, that serious effects were mostly tied to techniques other than Swedish massage, and concluded that serious events are probably true rarities.<a href=\"https://pubmed.ncbi.nlm.nih.gov/12777645/\">[15]</a> The U.S. center also advises against using massage to put off seeing a health care provider about a medical problem. The chair massage studies summarized below mostly did not report on adverse events one way or the other. Chair massage is short, done through clothing with moderate pressure, and does not include spinal manipulation. Serious events are rare: I ask about your health, medications, pregnancy and recent injuries before each session, even a short one at an event, and you can ask for lighter pressure or a pause at any time.</p>\n<!-- /wp:paragraph -->\n</details>\n<!-- /wp:details -->\n\n<!-- wp:details {\"style\":{\"border\":{\"width\":\"1px\",\"style\":\"solid\",\"color\":\"var(\\u002d\\u002dts-rule)\",\"radius\":\"4px\"},\"color\":{\"background\":\"var(\\u002d\\u002dts-panel)\"},\"spacing\":{\"padding\":{\"top\":\"0.85rem\",\"right\":\"1.1rem\",\"bottom\":\"0.85rem\",\"left\":\"1.1rem\"},\"margin\":{\"bottom\":\"0.7rem\"}},\"typography\":{\"fontWeight\":\"600\"}}} -->\n<details class=\"wp-block-details has-border-color has-background\" style=\"border-color:var(--ts-rule);border-width:1px;border-style:solid;border-radius:4px;background-color:var(--ts-panel);padding-top:0.85rem;padding-right:1.1rem;padding-bottom:0.85rem;padding-left:1.1rem;margin-bottom:0.7rem;font-weight:600\"><summary>Stress, Anxiety and Blood Pressure</summary>\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">Several workplace studies report less stress and lower blood pressure after chair massage. In 52 employees, systolic and diastolic blood pressure were lower after a 15-minute chair massage at work.<a href=\"https://pubmed.ncbi.nlm.nih.gov/9132704/\">[1]</a> In a study from the Touch Research Institute in Miami, 26 adults had a 15-minute chair massage and 24 sat in the massage chair to relax, twice a week for five weeks; anxiety was lower after the massage sessions but not the control sessions, brain-wave recordings in the massage group showed a pattern the authors read as alertness, the massage group became faster and more accurate at arithmetic, and at five weeks job-stress scores were lower only in the massage group.<a href=\"https://pubmed.ncbi.nlm.nih.gov/8884390/\">[16]</a> In 28 employees randomly assigned to weekly massage at work for four weeks or to no massage, strain and blood pressure fell during the four massage weeks in the massage group but not in the control group.<a href=\"https://pubmed.ncbi.nlm.nih.gov/20518225/\">[17]</a> In 48 insurance brokers at one company, 16 had a series of massages seated in a massage chair, 16 had them lying on a table and 16 had none; both massage groups improved on every burnout and anxiety measure, and the authors concluded that the position did not matter.<a href=\"https://pubmed.ncbi.nlm.nih.gov/29122258/\">[18]</a> In 59 young healthy adults, a 17-minute seated acupressure massage was followed by lower anxiety and higher self-confidence scores than sitting in the chair without massage, with a slightly lower heart rate and a rise in the hormone oxytocin.<a href=\"https://pubmed.ncbi.nlm.nih.gov/38318420/\">[19]</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">The limits are real. The 52-employee study had no comparison group, so the lower blood pressure cannot be separated from the effect of sitting quietly for 15 minutes.<a href=\"https://pubmed.ncbi.nlm.nih.gov/9132704/\">[1]</a> In the Miami study, salivary cortisol was lower after massage only on the first day, and depression scores fell in both groups.<a href=\"https://pubmed.ncbi.nlm.nih.gov/8884390/\">[16]</a> The 28-employee trial was small, and its abstract gives no figures.<a href=\"https://pubmed.ncbi.nlm.nih.gov/20518225/\">[17]</a> The seated-acupressure study found no link between cortisol levels and how people felt, and no change in CGRP or in the marker IL-6.<a href=\"https://pubmed.ncbi.nlm.nih.gov/38318420/\">[19]</a> In 60 nurses randomly assigned to a weekly 15-minute back massage for five weeks or to nothing, anxiety scores fell in the massage group and rose in the control group, but urinary cortisol and blood pressure did not differ significantly between the groups.<a href=\"https://pubmed.ncbi.nlm.nih.gov/16800217/\">[20]</a> In 365 on-site aromatherapy massages with music given to emergency nurses over two 12-week periods, anxiety measured before and after the sessions was lower afterward, but occupational stress scores did not change over the 12 weeks and sick leave did not differ.<a href=\"https://pubmed.ncbi.nlm.nih.gov/17727588/\">[21]</a> In 50 cardiac catheterization laboratory staff randomly assigned to 5 or 10 weekly 30-minute massages, with 10 further staff as controls, no significant effects were found on fatigue, pain, relaxation, stress or tension, even though 90 percent of appointments were used.<a href=\"https://pubmed.ncbi.nlm.nih.gov/22196566/\">[22]</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">What is encouraging is how consistently the short-term effect appears: in every study above that measured anxiety before and after sessions, it was lower afterward,<a href=\"https://pubmed.ncbi.nlm.nih.gov/8884390/\">[16]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/38318420/\">[19]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/17727588/\">[21]</a> and where massage was compared with sitting quietly in the same chair, the massage group did better.<a href=\"https://pubmed.ncbi.nlm.nih.gov/8884390/\">[16]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/38318420/\">[19]</a> Studies with a course of sessions over several weeks more often found changes in stress or burnout scores than single sessions did.<a href=\"https://pubmed.ncbi.nlm.nih.gov/8884390/\">[16]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/20518225/\">[17]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/29122258/\">[18]</a></p>\n<!-- /wp:paragraph -->\n</details>\n<!-- /wp:details -->\n\n<!-- wp:details {\"style\":{\"border\":{\"width\":\"1px\",\"style\":\"solid\",\"color\":\"var(\\u002d\\u002dts-rule)\",\"radius\":\"4px\"},\"color\":{\"background\":\"var(\\u002d\\u002dts-panel)\"},\"spacing\":{\"padding\":{\"top\":\"0.85rem\",\"right\":\"1.1rem\",\"bottom\":\"0.85rem\",\"left\":\"1.1rem\"},\"margin\":{\"bottom\":\"0.7rem\"}},\"typography\":{\"fontWeight\":\"600\"}}} -->\n<details class=\"wp-block-details has-border-color has-background\" style=\"border-color:var(--ts-rule);border-width:1px;border-style:solid;border-radius:4px;background-color:var(--ts-panel);padding-top:0.85rem;padding-right:1.1rem;padding-bottom:0.85rem;padding-left:1.1rem;margin-bottom:0.7rem;font-weight:600\"><summary>Desk Work, Muscle Discomfort and Movement</summary>\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">Several chair massage studies looked at the discomfort that comes with sitting at a computer. In 50 office workers, eight 15-minute chair massages over four weeks were followed by less pain in the upper and lower spine and the right arm and by higher pressure-pain thresholds at every muscle point tested, with the largest change in the shoulder muscles on the left side, while changes in the control group were not statistically significant.<a href=\"https://pubmed.ncbi.nlm.nih.gov/28157084/\">[5]</a> In 124 computer workers randomly assigned to four weeks of chair massage, relaxing music or nothing, chair massage raised the pressure-pain threshold in all the neck muscles tested and the relaxation level measured from heart-rate variability from 31.9 to 41.6 percent; music raised relaxation but left pain thresholds unchanged, with the threshold in one shoulder muscle falling, and changes in the control group were negligible.<a href=\"https://pubmed.ncbi.nlm.nih.gov/28721578/\">[6]</a> In 19 women in administration and management who had chair massage twice a week for a month, neck side-bending improved from 42.4 to 48.3 degrees, neck extension from 63.2 to 67.2 degrees, and discomfort scores for the neck and upper back fell.<a href=\"https://pubmed.ncbi.nlm.nih.gov/21688984/\">[4]</a> In 44 music students, eight 15-minute sessions of chair massage or exercises over four weeks raised the pressure-pain threshold at the most sensitive points in the upper shoulder muscles by 25 to 34 percent, most visibly in the massage group and from the fourth session on.<a href=\"https://pubmed.ncbi.nlm.nih.gov/32708600/\">[23]</a> In a crossover study of 17 healthy adults, muscle activity in the upper shoulder muscles fell by 19 percent after a short, moderate-pressure massage of the shoulders and neck, compared with 1 percent after sitting quietly.<a href=\"https://pubmed.ncbi.nlm.nih.gov/27977513/\">[24]</a> In a study from Thailand of 30 female administrative employees, 30 minutes of traditional Thai massage in each of three styles was followed by less forearm fatigue on muscle recordings.<a href=\"https://pubmed.ncbi.nlm.nih.gov/25892379/\">[25]</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">The limits: all 19 women in the Ljubljana study received the massage, only 15 completed it, and its authors’ claim that twice-weekly sessions beat a single session rests on comparing phases within the same small group.<a href=\"https://pubmed.ncbi.nlm.nih.gov/21688984/\">[4]</a> The 17-adult study measured muscle activity, not pain, and in the Thai study shoulder strength was not significantly different after massage.<a href=\"https://pubmed.ncbi.nlm.nih.gov/27977513/\">[24]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/25892379/\">[25]</a> In 45 cardiac sonographers randomly assigned to weekly 30-minute chair massage, massage plus stretching, or nothing for 10 weeks, discomfort scores improved somewhat in both massage groups, and the authors called for larger trials.<a href=\"https://pubmed.ncbi.nlm.nih.gov/20846441/\">[26]</a> An employer-funded program of 20-minute on-site massages for long-term care staff showed possible improvements in job satisfaction and an early reduction in pain severity, with the greatest benefit in people who already had symptoms, but no long-term effect was demonstrated.<a href=\"https://pubmed.ncbi.nlm.nih.gov/19104272/\">[27]</a> None of the studies that give their length followed people for longer than ten weeks.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">Still, the two office-worker studies are among the better-designed chair massage studies, with randomized control groups and an objective measure of pain sensitivity,<a href=\"https://pubmed.ncbi.nlm.nih.gov/28157084/\">[5]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/28721578/\">[6]</a> and together with the music-student study they agree that four weeks of short sessions changed how much pressure tender neck and shoulder muscles could take.<a href=\"https://pubmed.ncbi.nlm.nih.gov/28157084/\">[5]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/28721578/\">[6]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/32708600/\">[23]</a> In 29 nursing students who had both a firm and a very light seated massage, the firm one was rated better for energy, pain, stress and feeling physically tense, which is why I ask you about pressure rather than keeping it light by default.<a href=\"https://pubmed.ncbi.nlm.nih.gov/25140587/\">[28]</a></p>\n<!-- /wp:paragraph -->\n</details>\n<!-- /wp:details -->\n\n<!-- wp:details {\"style\":{\"border\":{\"width\":\"1px\",\"style\":\"solid\",\"color\":\"var(\\u002d\\u002dts-rule)\",\"radius\":\"4px\"},\"color\":{\"background\":\"var(\\u002d\\u002dts-panel)\"},\"spacing\":{\"padding\":{\"top\":\"0.85rem\",\"right\":\"1.1rem\",\"bottom\":\"0.85rem\",\"left\":\"1.1rem\"},\"margin\":{\"bottom\":\"0.7rem\"}},\"typography\":{\"fontWeight\":\"600\"}}} -->\n<details class=\"wp-block-details has-border-color has-background\" style=\"border-color:var(--ts-rule);border-width:1px;border-style:solid;border-radius:4px;background-color:var(--ts-panel);padding-top:0.85rem;padding-right:1.1rem;padding-bottom:0.85rem;padding-left:1.1rem;margin-bottom:0.7rem;font-weight:600\"><summary>Nurses, Hospital Staff and Carers</summary>\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">Hospitals have studied chair massage for their own staff and for visiting families. In 38 nurses offered a weekly 15-minute chair massage during work for 10 weeks, 329 of 400 appointments were used, and at 10 weeks perceived-stress scores had fallen from 17.85 to 14.92 and anxiety scores from 49.45 to 40.95, with better scores on a self-assessment scale and a symptom scale.<a href=\"https://pubmed.ncbi.nlm.nih.gov/23059434/\">[2]</a> In the randomized trial of 60 women on oncology nursing teams in São Paulo, 15-minute chair massages twice a week for three weeks were followed by lower stress scores than no massage, with an effect size (a Cohen’s d of 1.21) that counts as large, and less interference from pain in general activity, mood, work and sleep.<a href=\"https://pubmed.ncbi.nlm.nih.gov/34484493/\">[3]</a> In 12 hospital staff, mostly nurses, who had up to eight 15-minute Swedish massages at work, pain and tension were significantly lower, and relaxation and mood better, after massage, measured before and after each session.<a href=\"https://pubmed.ncbi.nlm.nih.gov/10603815/\">[29]</a> Evaluations of chair massage services for carers of inpatients at a cancer hospital in Manchester, England, reported better physical and emotional scores that were retained to the next day, better sleep, and feel-good scores that rose from 5 to 8 out of 10 on a transplant unit.<a href=\"https://pubmed.ncbi.nlm.nih.gov/15944109/\">[30]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/23890457/\">[31]</a> In a quality improvement project at an academic medical center in New Jersey, chair massage was among the brief on-site practices offered to nursing staff over 11 months, and its use rose over the period.<a href=\"https://pubmed.ncbi.nlm.nih.gov/42709485/\">[32]</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">Most of these are pilot studies or service evaluations without a comparison group, so they cannot show how much of the change came from the massage itself: the 38-nurse study, the 12-staff study and the two Manchester evaluations all compared people’s scores before and after massage, with no separate control group described.<a href=\"https://pubmed.ncbi.nlm.nih.gov/23059434/\">[2]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/10603815/\">[29]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/15944109/\">[30]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/23890457/\">[31]</a> The 2021 network meta-analysis found that massage reduced occupational stress in health care workers but that yoga did more, and the 2019 systematic review of aromatherapy and massage in nurses found that most studies reported a benefit but judged them too few and at too high a risk of bias to prove the effect.<a href=\"https://pubmed.ncbi.nlm.nih.gov/34235817/\">[9]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/29964364/\">[12]</a> In the 11-month project, staff perceptions of self-care opportunities and of a restorative work environment did not change significantly, and staffing and scheduling limited who could take part.<a href=\"https://pubmed.ncbi.nlm.nih.gov/42709485/\">[32]</a> In the cardiac catheterization laboratory study described above, weekly massages produced no statistically significant effects, although the authors’ feasibility test supported further research on fatigue, pain, relaxation and tension.<a href=\"https://pubmed.ncbi.nlm.nih.gov/22196566/\">[22]</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">The randomized oncology-nursing trial is the strongest chair massage study I found, and it is encouraging: six 15-minute sessions over three weeks were enough to show a large effect-size difference in stress between the groups.<a href=\"https://pubmed.ncbi.nlm.nih.gov/34484493/\">[3]</a> The uptake numbers say something on their own: 329 of 400 appointments used by the nurses, 90 percent of appointments used by the catheterization laboratory staff, and 227 chair massages given to carers over two years on one transplant unit.<a href=\"https://pubmed.ncbi.nlm.nih.gov/23059434/\">[2]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/22196566/\">[22]</a><a href=\"https://pubmed.ncbi.nlm.nih.gov/23890457/\">[31]</a></p>\n<!-- /wp:paragraph -->\n</details>\n<!-- /wp:details -->\n\n<!-- wp:details {\"style\":{\"border\":{\"width\":\"1px\",\"style\":\"solid\",\"color\":\"var(\\u002d\\u002dts-rule)\",\"radius\":\"4px\"},\"color\":{\"background\":\"var(\\u002d\\u002dts-panel)\"},\"spacing\":{\"padding\":{\"top\":\"0.85rem\",\"right\":\"1.1rem\",\"bottom\":\"0.85rem\",\"left\":\"1.1rem\"},\"margin\":{\"bottom\":\"0.7rem\"}},\"typography\":{\"fontWeight\":\"600\"}}} -->\n<details class=\"wp-block-details has-border-color has-background\" style=\"border-color:var(--ts-rule);border-width:1px;border-style:solid;border-radius:4px;background-color:var(--ts-panel);padding-top:0.85rem;padding-right:1.1rem;padding-bottom:0.85rem;padding-left:1.1rem;margin-bottom:0.7rem;font-weight:600\"><summary>Sources</summary>\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<p style=\"font-weight:400\">Each number above links to the source. Titles are quoted as published.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true,\"style\":{\"typography\":{\"fontWeight\":\"400\"}}} -->\n<ol class=\"wp-block-list\" style=\"font-weight:400\"><!-- wp:list-item -->\n<li><cite class=\"ts-source\">Cady SH, Jones GE. <a href=\"https://pubmed.ncbi.nlm.nih.gov/9132704/\">Massage therapy as a workplace intervention for reduction of stress</a>. Percept Mot Skills, 1997.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Engen DJ, Wahner-Roedler DL, Vincent A, Chon TY, Cha SS, Luedtke CA, Loehrer LL, Dion LJ, Rodgers NJ, Bauer BA. <a href=\"https://pubmed.ncbi.nlm.nih.gov/23059434/\">Feasibility and effect of chair massage offered to nurses during work hours on stress-related symptoms: a pilot study</a>. Complement Ther Clin Pract, 2012.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">de Souza TPB, Kurebayashi LFS, de Souza-Talarico JN, Turrini RNT. <a href=\"https://pubmed.ncbi.nlm.nih.gov/34484493/\">The effectiveness of Chair Massage on Stress and Pain in Oncology</a>. Int J Ther Massage Bodywork, 2021.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Siško PK, Videmšek M, Karpljuk D. <a href=\"https://pubmed.ncbi.nlm.nih.gov/21688984/\">The effect of a corporate chair massage program on musculoskeletal discomfort and joint range of motion in office workers</a>. J Altern Complement Med, 2011.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Cabak A, Kotynia P, Banasiński M, Obmiński Z, Tomaszewski W. <a href=\"https://pubmed.ncbi.nlm.nih.gov/28157084/\">The Concept of “Chair Massage” in the Workplace as Prevention of Musculoskeletal Overload and Pain</a>. Ortop Traumatol Rehabil, 2016.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Cabak A, Mikicin M, Łyp M, Stanisławska I, Kaczor R, Tomaszewski W. <a href=\"https://pubmed.ncbi.nlm.nih.gov/28721578/\">Preventive Chair Massage with Algometry to Maintain Psychosomatic Balance in White-Collar Workers</a>. Adv Exp Med Biol, 2017.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Mak S, Allen J, Begashaw M, Miake-Lye I, Beroes-Severin J, De Vries G, Lawson E, Shekelle PG. <a href=\"https://pubmed.ncbi.nlm.nih.gov/39008297/\">Use of Massage Therapy for Pain, 2018-2023: A Systematic Review</a>. JAMA Netw Open, 2024.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Crawford C, Boyd C, Paat CF, Price A, Xenakis L, Yang E, Zhang W; Evidence for Massage Therapy (EMT) Working Group. <a href=\"https://pubmed.ncbi.nlm.nih.gov/27165971/\">The Impact of Massage Therapy on Function in Pain Populations-A Systematic Review and Meta-Analysis of Randomized Controlled Trials: Part I, Patients Experiencing Pain in the General Population</a>. Pain Med, 2016.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Zhang M, Murphy B, Cabanilla A, Yidi C. <a href=\"https://pubmed.ncbi.nlm.nih.gov/34235817/\">Physical relaxation for occupational stress in healthcare workers: A systematic review and network meta-analysis of randomized controlled trials</a>. J Occup Health, 2021.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Moyer CA, Rounds J, Hannum JW. <a href=\"https://pubmed.ncbi.nlm.nih.gov/14717648/\">A meta-analysis of massage therapy research</a>. Psychol Bull, 2004.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Miake-Lye IM, Mak S, Lee J, Luger T, Taylor SL, Shanman R, Beroes-Severin JM, Shekelle PG. <a href=\"https://pubmed.ncbi.nlm.nih.gov/30892910/\">Massage for Pain: An Evidence Map</a>. J Altern Complement Med, 2019.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Li H, Zhao M, Shi Y, Xing Z, Li Y, Wang S, Ying J, Zhang M, Sun J. <a href=\"https://pubmed.ncbi.nlm.nih.gov/29964364/\">The effectiveness of aromatherapy and massage on stress management in nurses: A systematic review</a>. J Clin Nurs, 2019.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">National Center for Complementary and Integrative Health (NIH). <a href=\"https://www.nccih.nih.gov/health/massage-therapy-what-you-need-to-know\">Massage Therapy: What You Need To Know</a>. Last updated May 2019.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Yin P, Gao N, Wu J, Litscher G, Xu S. <a href=\"https://pubmed.ncbi.nlm.nih.gov/25197310/\">Adverse events of massage therapy in pain-related conditions: a systematic review</a>. Evid Based Complement Alternat Med, 2014.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Ernst E. <a href=\"https://pubmed.ncbi.nlm.nih.gov/12777645/\">The safety of massage therapy</a>. Rheumatology (Oxford), 2003.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Field T, Ironson G, Scafidi F, Nawrocki T, Goncalves A, Burman I, Pickens J, Fox N, Schanberg S, Kuhn C. <a href=\"https://pubmed.ncbi.nlm.nih.gov/8884390/\">Massage therapy reduces anxiety and enhances EEG pattern of alertness and math computations</a>. Int J Neurosci, 1996.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Day AL, Gillan L, Francis L, Kelloway EK, Natarajan M. <a href=\"https://pubmed.ncbi.nlm.nih.gov/20518225/\">Massage therapy in the workplace: reducing employee strain and blood pressure</a>. G Ital Med Lav Ergon, 2009.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Jaworska-Burzyńska L, Sekułowicz M, Cieślik B, Kowalska J, Szczepańska-Gieracha J. <a href=\"https://pubmed.ncbi.nlm.nih.gov/29122258/\">The role of massage in reducing the risk of burnout in employees of large corporations</a>. Complement Ther Clin Pract, 2017.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Fricker F, Barbotte MV, Pallot G, Radoua N, Sorci G, Heitz M, Brison G, Sales-Vuillemin E, Connat JL. <a href=\"https://pubmed.ncbi.nlm.nih.gov/38318420/\">Positive psychological effects of seated acupressure massage are associated with a rise in plasma oxytocin without affecting CGRP levels or circulating IL-6</a>. Compr Psychoneuroendocrinol, 2023.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Bost N, Wallis M. <a href=\"https://pubmed.ncbi.nlm.nih.gov/16800217/\">The effectiveness of a 15 minute weekly massage in reducing physical and psychological stress in nurses</a>. Aust J Adv Nurs, 2006.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Cooke M, Holzhauser K, Jones M, Davis C, Finucane J. <a href=\"https://pubmed.ncbi.nlm.nih.gov/17727588/\">The effect of aromatherapy massage with music on the stress and anxiety levels of emergency nurses: comparison between summer and winter</a>. J Clin Nurs, 2007.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Keller SR, Engen DJ, Bauer BA, Holmes DR Jr, Rihal CS, Lennon RJ, Loehrer LL, Wahner-Roedler DL. <a href=\"https://pubmed.ncbi.nlm.nih.gov/22196566/\">Feasibility and effectiveness of massage therapy for symptom relief in cardiac catheter laboratory staff: a pilot study</a>. Complement Ther Clin Pract, 2012.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Cygańska A, Truszczyńska-Baszak A, Tomaszewski P. <a href=\"https://pubmed.ncbi.nlm.nih.gov/32708600/\">Impact of Exercises and Chair Massage on Musculoskeletal Pain of Young Musicians</a>. Int J Environ Res Public Health, 2020.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Domingo AR, Diek M, Goble KM, Maluf KS, Goble DJ, Baweja HS. <a href=\"https://pubmed.ncbi.nlm.nih.gov/27977513/\">Short-duration therapeutic massage reduces postural upper trapezius muscle activity</a>. Neuroreport, 2017.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Yoopat P, Maes C, Poriau S, Vanwonterghem K. <a href=\"https://pubmed.ncbi.nlm.nih.gov/25892379/\">Thai traditional massage: efficiency-assessment of three traditional massage methods on office workers: an explorative study</a>. J Bodyw Mov Ther, 2015.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Engen DJ, Wahner-Roedler DL, Nadolny AM, Persinger CM, Oh JK, Spittell PC, Loehrer LL, Cha SS, Bauer BA. <a href=\"https://pubmed.ncbi.nlm.nih.gov/20846441/\">The effect of chair massage on muscular discomfort in cardiac sonographers: a pilot study</a>. BMC Complement Altern Med, 2010.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Back C, Tam H, Lee E, Haraldsson B. <a href=\"https://pubmed.ncbi.nlm.nih.gov/19104272/\">The effects of employer-provided massage therapy on job satisfaction, workplace stress, and pain and discomfort</a>. Holist Nurs Pract, 2009.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Turkeltaub PC, Yearwood EL, Friedmann E. <a href=\"https://pubmed.ncbi.nlm.nih.gov/25140587/\">Effect of a brief seated massage on nursing student attitudes toward touch for comfort care</a>. J Altern Complement Med, 2014.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Katz J, Wowk A, Culp D, Wakeling H. <a href=\"https://pubmed.ncbi.nlm.nih.gov/10603815/\">Pain and tension are reduced among hospital nurses after on-site massage treatments: a pilot study</a>. J Perianesth Nurs, 1999.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Mackereth P, Sylt P, Weinberg A, Campbell G. <a href=\"https://pubmed.ncbi.nlm.nih.gov/15944109/\">Chair massage for carers in an acute cancer hospital</a>. Eur J Oncol Nurs, 2005.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Nightingale L, Stringer J. <a href=\"https://pubmed.ncbi.nlm.nih.gov/23890457/\">Complementary therapy for carers on a transplant unit</a>. Complement Ther Clin Pract, 2013.</cite></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><cite class=\"ts-source\">Millspaugh J, Jameson BE, Cooper L. <a href=\"https://pubmed.ncbi.nlm.nih.gov/42709485/\">Advancing the Quadruple Aim Through Workplace-Integrated Holistic Wellness Interventions: A Quality Improvement Evaluation</a>. J Holist Nurs, 2026.</cite></li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n</details>\n<!-- /wp:details -->\n",
