\":0,\"blockTopPaddingMobile\":8,\"blockRightPaddingMobile\":0,\"blockLeftPaddingMobile\":0,\"blockBottomPaddingMobile\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-854ed516\"></div>\n<!-- /wp:uagb/advanced-heading -->\n\n<!-- wp:uagb/advanced-heading {\"block_id\":\"cd11ff0d\",\"classMigrate\":true,\"headingDescToggle\":true,\"subHeadingColor\":\"\",\"headSpace\":8,\"subHeadSpace\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-cd11ff0d\"><h3 class=\"uagb-heading-text\"><a href=\"/chair-massage/\">Chair Massage</a></h3><p class=\"uagb-desc-text\">Short, seated massage through your clothing, focused on the back, shoulders, neck, arms and hands: what I bring to employee appreciation days and workplace events, in a portable chair that fits in a quiet corner. <a href=\"/chair-massage/\">Learn about Chair Massage</a></p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n",
